import heapq


def order_tasks(dependencies):
    prerequisites = {
        task: set(required) for task, required in dependencies.items()
    }
    nodes = set(prerequisites)
    for required in prerequisites.values():
        nodes.update(required)

    dependents = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    for task, required in prerequisites.items():
        indegree[task] = len(required)
        for prerequisite in required:
            dependents[prerequisite].append(task)

    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        task = heapq.heappop(ready)
        result.append(task)
        for dependent in dependents[task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(result) != len(nodes):
        raise ValueError('dependencies contain a cycle')
    return result
```

