def wildcard_match(text: str, pattern: str) -> bool:
    width = len(pattern)
    previous = [False] * (width + 1)
    previous[0] = True
    for j, token in enumerate(pattern, 1):
        previous[j] = previous[j - 1] and token == '*'

    for char in text:
        current = [False] * (width + 1)
        for j, token in enumerate(pattern, 1):
            if token == '*':
                current[j] = current[j - 1] or previous[j]
            elif token == '?' or token == char:
                current[j] = previous[j - 1]
        previous = current
    return previous[-1]
