def median_two_sorted(a, b):
    if not a and not b:
        raise ValueError('Both lists are empty')
    if len(a) > len(b):
        a, b = b, a

    m, n = len(a), len(b)
    left_size = (m + n + 1) // 2
    low, high = 0, m
    infinity = float('inf')

    while low <= high:
        i = (low + high) // 2
        j = left_size - i
        a_left = a[i - 1] if i else -infinity
        a_right = a[i] if i < m else infinity
        b_left = b[j - 1] if j else -infinity
        b_right = b[j] if j < n else infinity

        if a_left <= b_right and b_left <= a_right:
            left_max = max(a_left, b_left)
            if (m + n) % 2:
                return float(left_max)
            return (left_max + min(a_right, b_right)) / 2.0
        if a_left > b_right:
            high = i - 1
        else:
            low = i + 1

    raise ValueError('No valid partition; inputs must be sorted')
