```python
def word_exists(board, word):
    if not word:
        return True
    if not board or not board[0]:
        return False

    rows, columns = len(board), len(board[0])
    if len(word) > rows * columns:
        return False
    visited = set()

    def search(row, col, index):
        if not (0 <= row < rows and 0 <= col < columns):
            return False
        if (row, col) in visited or board[row][col] != word[index]:
            return False
        if index == len(word) - 1:
            return True

        visited.add((row, col))
        for nr, nc in ((row - 1, col), (row + 1, col),
                       (row, col - 1), (row, col + 1)):
            if search(nr, nc, index + 1):
                visited.remove((row, col))
                return True
        visited.remove((row, col))
        return False

    return any(search(row, col, 0)
               for row in range(rows)
               for col in range(columns))
```

```python
def min_coins(coins, amount):
    denominations = sorted(set(coins))
    if amount < 0 or any(coin <= 0 for coin in denominations):
        raise ValueError('Amount must be nonnegative and coins positive')

    unreachable = amount + 1
    best = [unreachable] * (amount + 1)
    best[0] = 0
    for total in range(1, amount + 1):
        for coin in denominations:
            if coin > total:
                break
            best[total] = min(best[total], best[total - coin] + 1)
    return best[amount] if best[amount] != unreachable else -1
