def fibonacci(n, modulus=None):
    if n < 0:
        raise ValueError('n must be nonnegative')
    if modulus is not None and modulus <= 0:
        raise ValueError('modulus must be positive')

    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        if modulus is not None:
            c %= modulus
            d %= modulus
        if bit == '0':
            a, b = c, d
        else:
            a, b = d, c + d
            if modulus is not None:
                b %= modulus
    return a
