def luhn_valid(number):
    digits = []
    for char in number:
        if '0' <= char <= '9':
            digits.append(ord(char) - ord('0'))
        elif char not in ' -':
            return False
    if len(digits) < 2:
        return False

    total = 0
    for index, digit in enumerate(reversed(digits)):
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0
