    dp = [False] * (len(b) + 1)
    dp[0] = True
    for j in range(1, len(b) + 1):
        dp[j] = dp[j - 1] and b[j - 1] == target[j - 1]

    for i in range(1, len(a) + 1):
        dp[0] = dp[0] and a[i - 1] == target[i - 1]
        for j in range(1, len(b) + 1):
            ch = target[i + j - 1]
            dp[j] = (
