        raise ValueError('jump lengths must be nonnegative')
    if len(nums) <= 1:
        return 0

    jumps = 0
    boundary = 0
    farthest = 0
    for i in range(len(nums) - 1):
        farthest = max(farthest, i + nums[i])
        if i == boundary:
            if farthest <= i:
                return -1
            jumps += 1
            boundary = farthest
            if boundary >= len(nums) - 1:
                return jumps
