import math


def solve_quadratic(a, b, c):
    if a == 0:
        if b == 0:
            if c == 0:
                raise ValueError('the equation has infinitely many roots')
            return []
        return [float(-c / b)]

    discriminant = b * b - 4 * a * c
    if discriminant < 0:
        return []
    if discriminant == 0:
        return [float(-b / (2 * a))]

    root = math.sqrt(discriminant)
    q = -0.5 * (b + math.copysign(root, b))
    return sorted([float(q / a), float(c / q)])
