def mst_weight(n, edges):
    if n < 0:
        raise ValueError('n must be nonnegative')
    if n <= 1:
        return 0

    parent = list(range(n))
    size = [1] * n

    def find(vertex):
        while vertex != parent[vertex]:
            parent[vertex] = parent[parent[vertex]]
            vertex = parent[vertex]
        return vertex

    total = 0
    used = 0
    for u, v, weight in sorted(edges, key=lambda edge: edge[2]):
        ru, rv = find(u), find(v)
        if ru == rv:
            continue
        if size[ru] < size[rv]:
            ru, rv = rv, ru
        parent[rv] = ru
        size[ru] += size[rv]
        total += weight
        used += 1
        if used == n - 1:
            return total
    return None
