from collections import deque


def max_flow(capacities, source, sink):
    if source == sink:
        raise ValueError('source and sink must differ')

    residual = {source: {}, sink: {}}
    for u, neighbors in capacities.items():
        residual.setdefault(u, {})
        for v, capacity in neighbors.items():
            if capacity < 0:
                raise ValueError('capacities must be nonnegative')
            residual.setdefault(v, {})
            residual[u][v] = residual[u].get(v, 0) + capacity
            residual[v].setdefault(u, 0)

    total = 0
    while True:
        parent = {source: source}
        queue = deque([source])
        while queue and sink not in parent:
            u = queue.popleft()
            for v, capacity in residual[u].items():
                if capacity > 0 and v not in parent:
                    parent[v] = u
                    queue.append(v)
                    if v == sink:
                        break

        if sink not in parent:
            return total

        amount = None
        v = sink
        while v != source:
            u = parent[v]
            capacity = residual[u][v]
            amount = capacity if amount is None else min(amount, capacity)
            v = u

        v = sink
        while v != source:
            u = parent[v]
            residual[u][v] -= amount
            residual[v][u] += amount
            v = u
        total += amount
```

