def point_in_polygon(point, vertices):
    vertices = list(vertices)
    if len(vertices) < 3:
        return False

    px, py = point
    inside = False
    ax, ay = vertices[-1]
    for bx, by in vertices:
        cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
        if (
            cross == 0
            and min(ax, bx) <= px <= max(ax, bx)
            and min(ay, by) <= py <= max(ay, by)
        ):
            return True

        if (ay > py) != (by > py):
            if (cross > 0) == (by > ay):
                inside = not inside
        ax, ay = bx, by

    return inside
