import re


def expand_vars(template, variables):
    name_pattern = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    parts = []
    i = 0
    while i < len(template):
        if template[i] != '$':
            parts.append(template[i])
            i += 1
            continue

        if template.startswith('$$', i):
            parts.append('$')
            i += 2
            continue

        if template.startswith('${', i):
            end = template.find('}', i + 2)
            if end == -1:
                raise ValueError('unclosed variable expression')
            name = template[i + 2:end]
            if name_pattern.fullmatch(name) is None:
                raise ValueError('invalid variable name')
            i = end + 1
        else:
            match = name_pattern.match(template, i + 1)
            if match is None:
                raise ValueError('invalid dollar expression')
            name = match.group()
            i = match.end()

        parts.append(variables[name])
    return ''.join(parts)
