import re


def parse_http_headers(text):
    token = re.compile(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+")
    headers = {}
    previous = None

    for line in text.splitlines():
        if line == '':
            break
        if line[0] in ' \t':
            if previous is None:
                raise ValueError('continuation without a header')
            headers[previous][-1] += ' ' + line.strip(' \t')
            continue

        name, separator, value = line.partition(':')
        if not separator or token.fullmatch(name) is None:
            raise ValueError('invalid header line')
        previous = name.lower()
        headers.setdefault(previous, []).append(value.strip(' \t'))

    return headers
```

```python
def format_table(headers, rows):
    header = [str(value) for value in headers]
    body = [[str(value) for value in row] for row in rows]
    columns = len(header)
    if any(len(row) != columns for row in body):
        raise ValueError('inconsistent row lengths')
    if columns == 0:
        return ''

    widths = [len(cell) for cell in header]
    for row in body:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    def render(row):
        return ' | '.join(
            cell.ljust(width) for cell, width in zip(row, widths)
        )

    lines = [render(header), '-+-'.join('-' * width for width in widths)]
    lines.extend(render(row) for row in body)
    return '\n'.join(lines)
