def life_step(board):
    if not board:
        return []
    rows = len(board)
    columns = len(board[0])
    if any(len(row) != columns for row in board):
        raise ValueError('board must be rectangular')

    result = [[0] * columns for _ in range(rows)]
    for row in range(rows):
        for column in range(columns):
            neighbors = 0
            for r in range(max(0, row - 1), min(rows, row + 2)):
                for c in range(max(0, column - 1), min(columns, column + 2)):
                    if r != row or c != column:
                        neighbors += board[r][c]
            result[row][column] = int(
                neighbors == 3 or (board[row][column] == 1 and neighbors == 2)
            )
    return result
