        raise ValueError('n must be positive')

    numbers = [1]
    i2 = i3 = i5 = 0
    while len(numbers) < n:
        next2 = numbers[i2] * 2
        next3 = numbers[i3] * 3
        next5 = numbers[i5] * 5
        value = min(next2, next3, next5)
        numbers.append(value)
        if value == next2:
            i2 += 1
        if value == next3:
            i3 += 1
        if value == next5:
            i5 += 1
    return numbers[-1]
