from bisect import bisect_left


def min_ticket_cost(days, costs):
    days = sorted(set(days))
    costs = list(costs)
    if any(day <= 0 for day in days):
        raise ValueError('travel days must be positive')
    if len(costs) != 3 or any(cost < 0 for cost in costs):
        raise ValueError('expected three nonnegative pass costs')

    n = len(days)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = min(
            cost + dp[bisect_left(days, days[i] + duration, i, n)]
            for duration, cost in zip((1, 7, 30), costs)
        )
