from collections import defaultdict, deque


def word_ladder_length(begin, end, words):
    if begin == end:
        return 1
    width = len(begin)
    dictionary = {word for word in words if len(word) == width}
    if len(end) != width or end not in dictionary:
        return 0
    dictionary.add(begin)

    buckets = defaultdict(list)
    for word in dictionary:
        for i in range(width):
            buckets[word[:i] + '*' + word[i + 1:]].append(word)

    queue = deque([(begin, 1)])
    visited = {begin}
    while queue:
        word, distance = queue.popleft()
        for i in range(width):
            pattern = word[:i] + '*' + word[i + 1:]
            for neighbor in buckets.pop(pattern, ()):
                if neighbor == end:
                    return distance + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))
    return 0
```

