class Autocomplete:
    def __init__(self, words=()):
        self._root = {}
        for word in words:
            self.add(word)

    def add(self, word):
        node = self._root
        for char in word:
            node = node.setdefault(char, {})
        node[None] = True

    def suggest(self, prefix, limit=5):
        if limit < 0:
            raise ValueError('limit must be nonnegative')
        if limit == 0:
            return []

        node = self._root
        for char in prefix:
            if char not in node:
                return []
            node = node[char]

        result = []
        stack = [(node, prefix)]
        while stack and len(result) < limit:
            node, word = stack.pop()
            if None in node:
                result.append(word)
                if len(result) == limit:
                    break
            for char in sorted((key for key in node if key is not None), reverse=True):
                stack.append((node[char], word + char))
        return result
