from bisect import bisect_right


def linear_interpolate(xs, ys, x):
    if len(xs) != len(ys) or not xs:
        raise ValueError('samples must have equal nonzero lengths')
    if any(xs[i] >= xs[i + 1] for i in range(len(xs) - 1)):
        raise ValueError('xs must be strictly increasing')

    if x <= xs[0]:
        return ys[0]
    if x >= xs[-1]:
        return ys[-1]

    left = bisect_right(xs, x) - 1
    fraction = (x - xs[left]) / (xs[left + 1] - xs[left])
    return (1 - fraction) * ys[left] + fraction * ys[left + 1]
```

