def wildcard_match(text, pattern):
    i = j = 0
    star = -1
    star_end = 0

    while i < len(text):
        if j < len(pattern) and pattern[j] == '*':
            star = j
            star_end = i
            j += 1
        elif j < len(pattern) and (
            pattern[j] == '?' or pattern[j] == text[i]
        ):
            i += 1
            j += 1
        elif star != -1:
            star_end += 1
            i = star_end
            j = star + 1
        else:
            return False

    while j < len(pattern) and pattern[j] == '*':
        j += 1
    return j == len(pattern)
