def brackets_balanced(text):
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []
    quote = None
    escaped = False

    for char in text:
        if quote is not None:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == quote:
                quote = None
        elif char == "'" or char == '"':
            quote = char
        elif char in '([{':
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False

    return quote is None and not stack
