```python
def decode_repetition(text):
    stack = []
    parts = []
    i = 0

    while i < len(text):
        char = text[i]
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
            parts.append(char)
            i += 1
        elif '0' <= char <= '9':
            end = i
            while end < len(text) and '0' <= text[end] <= '9':
                end += 1
            if end == len(text) or text[end] != '[':
                raise ValueError('count must be followed by an opening bracket')
            count = int(text[i:end])
            stack.append((parts, count))
            parts = []
            i = end + 1
        elif char == ']':
            if not stack:
                raise ValueError('unmatched closing bracket')
            outer, count = stack.pop()
            outer.append(''.join(parts) * count)
            parts = outer
            i += 1
        else:
            raise ValueError('invalid character or unexpected opening bracket')

    if stack:
        raise ValueError('unclosed group')
    return ''.join(parts)
```

