import heapq
from itertools import count


def shortest_paths(graph, start):
    adjacency = {node: list(edges) for node, edges in graph.items()}
    for edges in list(adjacency.values()):
        for neighbor, weight in edges:
            if weight < 0:
                raise ValueError('Dijkstra requires nonnegative weights')
            adjacency.setdefault(neighbor, [])
    adjacency.setdefault(start, [])

    distances = {node: float('inf') for node in adjacency}
    distances[start] = 0
    sequence = count()
    heap = [(0, next(sequence), start)]

    while heap:
        distance, _, node = heapq.heappop(heap)
        if distance != distances[node]:
            continue
        for neighbor, weight in adjacency[node]:
            candidate = distance + weight
            if candidate < distances[neighbor]:
                distances[neighbor] = candidate
                heapq.heappush(heap, (candidate, next(sequence), neighbor))

    return distances
```

