from collections import deque


def shortest_grid_path(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return None
    columns = len(grid[0])
    if any(len(row) != columns for row in grid):
        raise ValueError('grid must be rectangular')
    if columns == 0:
        return None

    start, goal = tuple(start), tuple(goal)

    def is_open(position):
        row, col = position
        return (
            0 <= row < rows
            and 0 <= col < columns
            and grid[row][col] == 0
        )

    if not is_open(start) or not is_open(goal):
        return None

    queue = deque([start])
    parent = {start: None}
    directions = ((-1, 0), (0, -1), (0, 1), (1, 0))
    while queue:
        current = queue.popleft()
        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = parent[current]
            return path[::-1]

        row, col = current
        for dr, dc in directions:
            neighbor = (row + dr, col + dc)
            if neighbor not in parent and is_open(neighbor):
                parent[neighbor] = current
                queue.append(neighbor)
    return None
```

