        raise ValueError('target must be nonnegative')
    counts = [0] * (target + 1)
    counts[0] = 1

    for number in nums:
        if number < 0:
            raise ValueError('numbers must be nonnegative')
        for total in range(target, number - 1, -1):
            counts[total] += counts[total - number]
