from collections import deque


def moving_average(readings, window):
    if window <= 0:
        raise ValueError('window must be positive')

    def generate():
        recent = deque()
        total = 0
        for reading in readings:
            recent.append(reading)
            total += reading
            if len(recent) > window:
                total -= recent.popleft()
            if len(recent) == window:
                yield total / window

    return generate()
