import time


class TTLCache:
    def __init__(self, ttl, timer=time.monotonic):
        if ttl < 0:
            raise ValueError('ttl must be nonnegative')
        self._ttl = ttl
        self._timer = timer
        self._entries = {}

    def set(self, key, value):
        self._entries[key] = (self._timer() + self._ttl, value)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        expires_at, value = entry
        if self._timer() >= expires_at:
            del self._entries[key]
            return default
        return value

    def __len__(self):
        now = self._timer()
        expired = [
            key for key, (expires_at, _) in self._entries.items()
            if now >= expires_at
        ]
        for key in expired:
            del self._entries[key]
        return len(self._entries)
```

