        raise ValueError('n must be nonnegative')

    data = bytearray()
    while len(data) < n:
        chunk = stream.read(n - len(data))
        if not chunk:
            raise EOFError(f'expected {n} bytes, received {len(data)}')
        data.extend(chunk)
