def pack_bits(bits):
    result = bytearray()
    current = 0
    count = 0
    for bit in bits:
        if not isinstance(bit, int) or bit not in (0, 1):
            raise ValueError('each bit must be an integer 0 or 1')
        current = (current << 1) | bit
        count += 1
        if count == 8:
            result.append(current)
            current = 0
            count = 0

    if count:
        result.append(current << (8 - count))
    return bytes(result)
