import re


def parse_int_ranges(text):
    if not text.strip():
        return []

    result = []
    pattern = r'\s*([+-]?[0-9]+)(?:\s*-\s*([+-]?[0-9]+))?\s*'
    for piece in text.split(','):
        match = re.fullmatch(pattern, piece)
        if match is None:
            raise ValueError('invalid integer or range')
        start = int(match.group(1))
        end = start if match.group(2) is None else int(match.group(2))
        if end < start:
            raise ValueError('descending range')
        result.extend(range(start, end + 1))
    return result
