from itertools import zip_longest


def compare_versions(a, b):
    def parse(version):
        parts = version.split('.')
        if any(not part or any(c < '0' or c > '9' for c in part)
               for part in parts):
            raise ValueError('invalid version')
        return [part.lstrip('0') or '0' for part in parts]

    left, right = parse(a), parse(b)
    for x, y in zip_longest(left, right, fillvalue='0'):
        x_key, y_key = (len(x), x), (len(y), y)
        if x_key < y_key:
            return -1
        if x_key > y_key:
            return 1
    return 0
