def median_two_sorted(a, b):
    if len(a) > len(b):
        return median_two_sorted(b, a)
    m, n = len(a), len(b)
    if n == 0:
        raise ValueError('both lists are empty')

    half = (m + n + 1) // 2
    low, high = 0, m
    infinity = float('inf')
    while low <= high:
        i = (low + high) // 2
        j = half - i
        left_a = a[i - 1] if i else -infinity
        right_a = a[i] if i < m else infinity
        left_b = b[j - 1] if j else -infinity
        right_b = b[j] if j < n else infinity

        if left_a <= right_b and left_b <= right_a:
            lower = max(left_a, left_b)
            if (m + n) % 2:
                return lower
            return (lower + min(right_a, right_b)) / 2
        if left_a > right_b:
            high = i - 1
        else:
            low = i + 1

    raise ValueError('inputs must be sorted')
