def min_coins(coins, amount):
    if amount < 0:
        raise ValueError('amount must be nonnegative')
    denominations = sorted(set(coins))
    if any(coin <= 0 for coin in denominations):
        raise ValueError('coin denominations must be positive')

    unreachable = amount + 1
    dp = [unreachable] * (amount + 1)
    dp[0] = 0
    for subtotal in range(1, amount + 1):
        for coin in denominations:
            if coin > subtotal:
                break
            dp[subtotal] = min(dp[subtotal], dp[subtotal - coin] + 1)
    return -1 if dp[amount] == unreachable else dp[amount]
