def maximal_square_area(grid):
    if not grid:
        return 0
    cols = len(grid[0])
    if any(len(row) != cols for row in grid):
        raise ValueError('grid must be rectangular')

    dp = [0] * (cols + 1)
    best = 0
    for row in grid:
        diagonal = 0
        for j, value in enumerate(row, 1):
            above = dp[j]
            if value == 1:
                dp[j] = 1 + min(above, dp[j - 1], diagonal)
                best = max(best, dp[j])
            else:
                dp[j] = 0
            diagonal = above
    return best * best
