        return None

    copies = {id(node): Node(node.val)}
    queue = deque([node])
    while queue:
        original = queue.popleft()
        copy = copies[id(original)]
        for neighbor in original.neighbors:
            identity = id(neighbor)
            if identity not in copies:
                copies[identity] = Node(neighbor.val)
                queue.append(neighbor)
            copy.neighbors.append(copies[identity])
