from collections import deque


def min_lock_turns(deadends, target):
    blocked = set(deadends)
    start = '0000'
    if start in blocked or target in blocked:
        return -1

    seen = blocked | {start}
    queue = deque([(start, 0)])
    while queue:
        state, distance = queue.popleft()
        if state == target:
            return distance
        for i, character in enumerate(state):
            digit = int(character)
            for step in (-1, 1):
                replacement = str((digit + step) % 10)
                neighbor = state[:i] + replacement + state[i + 1:]
                if neighbor not in seen:
                    seen.add(neighbor)
                    queue.append((neighbor, distance + 1))
    return -1
