class RangeSum2D:
    def __init__(self, matrix):
        self._rows = len(matrix)
        self._cols = len(matrix[0]) if matrix else 0
        if any(len(row) != self._cols for row in matrix):
            raise ValueError('matrix must be rectangular')

        prefix = [
            [0] * (self._cols + 1)
            for _ in range(self._rows + 1)
        ]
        for r, row in enumerate(matrix, 1):
            row_total = 0
            for c, value in enumerate(row, 1):
                row_total += value
                prefix[r][c] = prefix[r - 1][c] + row_total
        self._prefix = prefix

    def sum_region(self, r1, c1, r2, c2):
        if not (0 <= r1 <= r2 <= self._rows and
                0 <= c1 <= c2 <= self._cols):
            raise ValueError('invalid rectangle bounds')
        p = self._prefix
        return p[r2][c2] - p[r1][c2] - p[r2][c1] + p[r1][c1]
